'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var Float64Array = require( '@stdlib/array/float64' );
var ccis = require( './../lib/strided.js' );


// FIXTURES //

var pureReal = require( './fixtures/julia/pure_real.json' );
var generalComplex = require( './fixtures/julia/general_complex.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ccis, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the cis function', function test( t ) {
	var expected;
	var out;
	var z;
	var v;

	z = new Float64Array( [ 0.0, 0.0 ] );
	out = new Float64Array( 2 );
	v = ccis( z, 1, 0, out, 1, 0 );

	expected = new Float64Array( [ 1.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	out = new Float64Array( 4 );
	v = ccis( z, 2, 0, out, 2, 0 );

	expected = new Float64Array( [ 1.0, 0.0, 0.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	out = new Float64Array( 4 );
	v = ccis( z, 2, 1, out, 2, 1 );

	expected = new Float64Array( [ 0.0, 1.0, 0.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	z = new Float64Array( [ 0.0, 0.0 ] );
	out = new Float64Array( 4 );
	v = ccis( z, -1, 1, out, -2, 3 );

	expected = new Float64Array( [ 0.0, 0.0, 0.0, 1.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function computes cis(z) for pure real z', function test( t ) {
	var expected;
	var cisre;
	var cisim;
	var out;
	var re;
	var im;
	var z;
	var i;

	re = pureReal.re;
	im = pureReal.im;
	cisre = pureReal.cisre;
	cisim = pureReal.cisim;

	z = new Float64Array( 2 );
	out = new Float64Array( 2 );

	for ( i = 0; i < re.length; i++ ) {
		z[ 0 ] = re[ i ];
		z[ 1 ] = im[ i ];
		ccis( z, 1, 0, out, 1, 0 );
		expected = new Float64Array( [ cisre[ i ], cisim[ i ] ] );
		t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes cis(z) for complex z', function test( t ) {
	var expected;
	var cisre;
	var cisim;
	var out;
	var re;
	var im;
	var z;
	var i;

	re = generalComplex.re;
	im = generalComplex.im;
	cisre = generalComplex.cisre;
	cisim = generalComplex.cisim;

	z = new Float64Array( 2 );
	out = new Float64Array( 2 );

	for ( i = 0; i < re.length; i++ ) {
		z[ 0 ] = re[ i ];
		z[ 1 ] = im[ i ];
		ccis( z, 1, 0, out, 1, 0 );
		expected = new Float64Array( [ cisre[ i ], cisim[ i ] ] );
		t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if real component is `+Infinity`, all components are `NaN`', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ PINF, 0.0 ] );

	ccis( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity`, all components are `NaN`', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ NINF, 0.0 ] );

	ccis( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `+Infinity`, all components are zero', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ 1.0, PINF ] );

	ccis( z, 1, 0, out, 1, 0 );
	t.strictEqual( out[ 0 ], 0.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 0.0, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `-Infinity`, the function computes the correct result according to IEEE 754 rules', function test( t ) {
	var out = new Float64Array( 2 );
	var z = new Float64Array( [ 0.0, NINF ] );

	ccis( z, 1, 0, out, 1, 0 );

	// The real component is computed as Infinity * 1.0 = Infinity:
	t.strictEqual( out[ 0 ], PINF, 'returns expected value' );

	// The imaginary component is computed as Infinity * 0.0 = NaN:
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if a real or imaginary component is `NaN`, all components are `NaN`', function test( t ) {
	var out;
	var z;

	z = new Float64Array( [ NaN, 3.0 ] );
	out = new Float64Array( 2 );
	ccis( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	z = new Float64Array( [ 5.0, NaN ] );
	out = new Float64Array( 2 );
	ccis( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	z = new Float64Array( [ NaN, NaN ] );
	out = new Float64Array( 2 );
	ccis( z, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	t.end();
});
